def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    h = max(0, int(horizon))
    x = [float(v) for v in history if isinstance(v, (int, float)) and math.isfinite(float(v))]
    if h == 0:
        return []
    if not x:
        return [0.0] * h
    if len(x) < 8:
        level = statistics.median(x)
        return [level] * h

    def level_value(a):
        return statistics.median(a[-min(12, len(a)):])

    def slope_value(a, window):
        n = min(window, len(a) - 1)
        diffs = [a[i] - a[i - 1] for i in range(len(a) - n, len(a))]
        slope = statistics.median(diffs) if diffs else 0.0
        center = statistics.median(diffs) if diffs else 0.0
        mad = statistics.median([abs(d - center) for d in diffs]) if diffs else 0.0
        bound = max(3.0 * mad, 0.02 * max(1.0, abs(level_value(a))))
        return max(-bound, min(bound, slope))

    def trend_value(a, step, window, decay):
        slope = slope_value(a, window)
        if decay == 1.0:
            movement = slope * step
        else:
            movement = slope * (1.0 - decay ** step) / (1.0 - decay)
        value = a[-1] + movement
        return value if math.isfinite(value) else level_value(a)

    windows = [8, 16, 32]
    decays = [0.90, 0.97, 0.99, 1.0]
    candidates = [(w, d) for w in windows for d in decays]
    base_errors = []
    candidate_errors = {c: [] for c in candidates}
    start = max(8, len(x) - min(96, len(x) // 2))
    steps = [1, 4, 12, 24]
    for origin in range(start, len(x) - 1):
        prefix = x[:origin]
        base = level_value(prefix)
        for step in steps:
            target_index = origin + step - 1
            if target_index >= len(x):
                continue
            target = x[target_index]
            base_errors.append(abs(target - base))
            for c in candidates:
                candidate_errors[c].append(abs(target - trend_value(prefix, step, c[0], c[1])))

    base_score = statistics.median(base_errors) if base_errors else float('inf')
    best = None
    best_score = float('inf')
    for c in candidates:
        errors = candidate_errors[c]
        if len(errors) >= 24:
            score = statistics.median(errors)
            if score < best_score:
                best = c
                best_score = score

    level = level_value(x)
    if best is None or not math.isfinite(base_score) or base_score <= 0.0 or best_score >= 0.97 * base_score:
        return [float(level)] * h

    improvement = max(0.0, min(1.0, 1.0 - best_score / base_score))
    weight = min(0.65, improvement / 0.20)
    out = []
    for step in range(1, h + 1):
        trend = trend_value(x, step, best[0], best[1])
        value = (1.0 - weight) * level + weight * trend
        out.append(float(value) if math.isfinite(value) else float(level))
    return out
